def select_pod(self, tenant_id: str, prefix_bytes: bytes, pod_loads: dict[str, float], avg_load: float) -> str:
        if not tenant_id:
            raise ValueError('tenant_id is required for cache isolation')
        salted_key = hashlib.blake2b(
            tenant_id.encode('utf-8') + b':' + prefix_bytes[:2048],
            digest_size=16,
        ).hexdigest()
        candidates = self.ring.get_candidates(salted_key, count=3)
        if not candidates:
            raise RuntimeError('No healthy GPU worker pods available')
        cap = max(1.0, avg_load * self.max_load_factor)
        for pod_id in candidates:
            if pod_loads.get(pod_id, 0.0) <= cap:
                return pod_id
        # All candidates busy: pick least-loaded among candidates to bound TTFT
        return min(candidates, key=lambda p: pod_loads.get(p, 0.0))
